 ReleaseFloatingTE(TDialogTEView* aDialogTEView);		// Places the specified TDialogTEView in the cache, or frees it if the cache is        // full.	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	CAutoPtr_AC<TDialogTEView> fCache;};#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/30/96	Make all constructors use initialization lists if they weren't already							doing do. Switch several more empty constructors to inlines.		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/